export default function Hero() {
  const containerRef = useRef<HTMLDivElement>(null);
  const leftRectRef = useRef<SVGRectElement>(null);
  const rightRectRef = useRef<SVGRectElement>(null);
  const blueprintGlowRef = useRef<HTMLDivElement>(null);
  const [particles, setParticles] = useState<Particle[]>([]);
  const [showTheme, setShowTheme] = useState(false);

  useEffect(() => {
    const generatedParticles: Particle[] = [...Array(60)].map(() => ({
      left: Math.random() * 100,
      top: Math.random() * 100,
      size: Math.random() * 3 + 2,
      duration: Math.random() * 4 + 3,
      delay: Math.random() * 2,
    }));
    setParticles(generatedParticles);
  }, []);

  useEffect(() => {
    requestAnimationFrame(() => {
      const tl = gsap.timeline({ delay: 0.5 });

      // Animate left clip from 0 to 583.5 (full left half)
      tl.to(leftRectRef.current, {
        attr: { width: 583.5 },
        duration: 2.8,
        ease: 'power4.out',
      }, 0);

      // Animate right clip x position from 1167 (right edge) to 583.5 (center)
      tl.to(rightRectRef.current, {
        attr: { x: 583.5 },
        duration: 2.8,
        ease: 'power4.out',
      }, 0);

      // Glow
      tl.to(blueprintGlowRef.current, {
        opacity: 1,
        duration: 0.2,
      }, 2.8);

      tl.to(blueprintGlowRef.current, {
        opacity: 0,
        duration: 0.4,
      }, 3.0);

      // Theme text
      tl.call(() => {
        setShowTheme(true);
      }, [], 3.4);

      tl.to(blueprintGlowRef.current, {
        opacity: 0.15,
        duration: 0.8,
      }, 3.4);
    });
  }, []);

  const scrollToContent = () => {
    window.scrollTo({
      top: window.innerHeight,
      behavior: 'smooth',
    });
  };

  return (
    <section
      id="hero"
      ref={containerRef}
      className="relative w-full min-h-screen flex items-center justify-center overflow-hidden"
      style={{ backgroundColor: '#050505' }}
    >
      {/* Animated background circles */}
      <motion.div
        className="absolute top-20 right-10 w-96 h-96 rounded-full mix-blend-screen filter blur-3xl opacity-20"
        style={{ background: 'radial-gradient(circle, #E0272C, transparent)' }}
        animate={{
          y: [0, 50, 0],
          x: [0, 30, 0],
          scale: [1, 1.2, 1],
        }}
        transition={{ duration: 8, repeat: Infinity }}
      />
      <motion.div
        className="absolute bottom-20 left-10 w-96 h-96 rounded-full mix-blend-screen filter blur-3xl opacity-20"
        style={{ background: 'radial-gradient(circle, #E0272C, transparent)' }}
        animate={{
          y: [0, -50, 0],
          x: [0, -30, 0],
          scale: [1, 1.15, 1],
        }}
        transition={{ duration: 10, repeat: Infinity }}
      />

      {/* Grid lines overlay */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none opacity-10">
        <defs>
          <pattern id="grid" width="50" height="50" patternUnits="userSpaceOnUse">
            <path d="M 50 0 L 0 0 0 50" fill="none" stroke="rgba(224, 39, 44, 0.15)" strokeWidth="0.5" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#grid)" />
      </svg>
      {/* Floating particles */}
      {particles.map((particle, i) => (
        <motion.div
          key={i}
          className="absolute rounded-full"
          style={{
            left: `${particle.left}%`,
            top: `${particle.top}%`,
            width: `${particle.size}px`,
            height: `${particle.size}px`,
            background: '#E0272C',
            boxShadow: '0 0 10px rgba(224, 39, 44, 0.8), 0 0 20px rgba(224, 39, 44, 0.4)',
            opacity: 0.6,
          }}
          animate={{
            y: [0, -120, 0],
            x: [0, Math.random() * 60 - 30, 0],
            opacity: [0.3, 0.7, 0.3],
            rotate: [0, 360],
            scale: [0.8, 1.2, 0.8],
          }}
          transition={{
            duration: particle.duration,
            repeat: Infinity,
            delay: particle.delay,
            ease: 'easeInOut',
          }}
        />
      ))}

      {/* Radial overlay for depth */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          backgroundImage: 'radial-gradient(circle at 50% 50%, transparent 0%, rgba(5, 5, 5, 0.6) 100%)',
        }}
      />

      {/* Blueprint - Single SVG with animated clip paths */}
      <div className="absolute inset-0 flex justify-center items-center z-10 pointer-events-none sm:pt-48 pt-32">
        <svg
          viewBox="0 0 1167 341"
          className="sm:w-[95vw] w-full sm:max-w-6xl max-w-none px-2 h-auto"
          preserveAspectRatio="xMidYMid meet"
          xmlns="http://www.w3.org/2000/svg"
        >
          <defs>
            <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur stdDeviation="1.5" result="blur1" />
              <feMerge>
                <feMergeNode in="blur1" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
            <clipPath id="leftClip">
              <rect ref={leftRectRef} x="0" y="0" width="0" height="341" />
            </clipPath>
            <clipPath id="rightClip">
              <rect ref={rightRectRef} x="1167" y="0" width="583.5" height="341" />
            </clipPath>
          </defs>
          
          {/* Left half - expands from 0 to 583.5 width */}
          <g clipPath="url(#leftClip)">
            <path fill="#E0272C" opacity="0.95" filter="url(#glow)" fillRule="evenodd" d={BLUEPRINT_SVG_PATH} />
          </g>
          
          {/* Right half - expands from 0 to 583.5 width, starts at x=583.5 */}
          <g clipPath="url(#rightClip)">
            <path fill="#E0272C" opacity="0.95" filter="url(#glow)" fillRule="evenodd" d={BLUEPRINT_SVG_PATH} />
          </g>
        </svg>
      </div>

      {/* Glow effect at center */}
      <div
        ref={blueprintGlowRef}
        className="absolute inset-0 pointer-events-none"
        style={{
          opacity: 0,
          background: 'radial-gradient(ellipse 300px 400px at center, rgba(224, 39, 44, 0.4), transparent)',
          filter: 'blur(40px)',
        }}
      />

      {/* Theme Text Section */}
      {showTheme && (
        <motion.div
          className="absolute inset-0 flex flex-col items-center justify-start z-20 pointer-events-none sm:pt-24 pt-8"
          initial={{ opacity: 0, y: 40, scale: 0.92 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          transition={{ duration: 0.9, ease: 'easeOut' }}
        >
          <div className="text-center" style={{ perspective: "1000px" }}>
            <motion.h1 
              className="text-4xl sm:text-5xl md:text-7xl font-bold mb-4 drop-shadow-lg"
              initial={{ 
                opacity: 1,
                scale: 8,
                y: -200,
                rotateX: 90,
              }}
              animate={{ 
                opacity: 1,
                scale: 1,
                y: 0,
                rotateX: 0,
              }}
              transition={{ 
                duration: 2.5,
                ease: "easeInOut"
              }}
              style={{
                transformOrigin: "center center",
              }}
            >
              <span className="text-[#E0272C]">TEDX</span>
              <span className="text-white">GeethanjaliCET</span>
            </motion.h1>
            
            
          </div>
        </motion.div>
      )}

      {/* Scroll Indicator */}
      <motion.button
        onClick={scrollToContent}
        className="absolute bottom-8 left-1/2 transform -translate-x-1/2 z-20 text-white hover:text-[#E0272C] transition-colors"
        animate={{ y: [0, 8, 0] }}
        transition={{ duration: 2, repeat: Infinity }}
      >
        <ChevronDown size={32} />
      </motion.button>
    </section>
  );
}
